"""Round 7: the result documents docs/03_results/ROUND7_A.md and ROUND7_B.md, generated from results/results.json and results/tables/r7_*.json.

    python -m crashguard.r7_docs
"""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
T = ROOT / "results" / "tables"
HEAD = """# {title}

<!-- header:start -->
| Field | Value |
|---|---|
| Status | current |
| Date | 2026-11-16 |
| Owner | Mritula S |
| Scope | {scope} |
| Evidence labels used | {labels} |
| Abbreviations | ACK = acknowledgement frame; AEAD = authenticated encryption with associated data; PRF = pseudorandom function; SF = spreading factor (LoRa) |
<!-- header:end -->

"""


def K() -> dict:
    return {e["name"]: e["value"] for e in json.loads((ROOT / "results" / "results.json").read_text(encoding="utf-8"))}


def f(x, d=3):
    return "NOT_RUN" if x is None or x == "NOT_RUN" else (f"{x:.{d}f}" if isinstance(x, float) else str(x))


def doc_a(R: dict) -> str:
    cells = json.loads((T / "r7_attack_cells.json").read_text(encoding="utf-8"))
    post = json.loads((T / "r7_attack_posthoc.json").read_text(encoding="utf-8"))
    form = json.loads((T / "r7_formal.json").read_text(encoding="utf-8"))
    a2 = json.loads((T / "r7_trace_cells.json").read_text(encoding="utf-8"))
    L = [HEAD.format(title="Round 7 A: duty-budget exhaustion and the reserved-budget policy", scope="The attack, the analytic bounds, the simulation (H-R7-A1), the bounded formal check, the benign cost on traces (H-R7-A2) and the re-derived gating rule (H-R7-A3).", labels="ANALYTICAL, SIMULATED, TRACE_DRIVEN, FORMAL")]
    L.append("Generated by `python -m crashguard.r7_docs` from `results/results.json` (keys `r7.a.*`, `r7.a1.*`, `r7.a2.*`, `r7.formal.*`). Hypotheses as written in `docs/02_preregistration/PREREGISTRATION_V18.md`; the verdicts are in `ROUND7_RESULTS.md`.\n")
    L.append("## 1. Retry policy of the shipped node (read from code)\n")
    L.append("Per event one FIFO queue: the flash (14 bytes, at most 4 tries), then the confirm (97 bytes, or the 13-byte micro-confirm after an acknowledged flash; at most 4 tries) or three unconfirmed cancels 0.3 s apart. Each confirmed try is followed by the receive windows (0.32 s in ns-3). Nothing is withdrawn when the full decision is ready and no frame type has priority; a frame waits for the duty model with no deadline. Heartbeats are unconfirmed, so ACK suppression does not touch them. The firmware has no two-stage queue; the policy exists in `xsim/ns3/xsim_alert.cc` (r3t, r6m) and in the trace replay.\n")
    L.append("## 2. Attack and bounds (ANALYTICAL)\n")
    L.append("Inputs: time on air `crashguard.lora.airtime_ms`; the attacker suppresses every ACK, cannot forge a tag, and is not bound by a duty limit (its cost is an upper bound: it jams the whole 26-byte ACK of each of the 8 frames). Frames that fail the tag trigger only cell-level rate limiting and are not sent by the node, so they do not touch its budget.\n")
    L.append("| SF | A14 (s) | A97 (s) | node airtime per event (s) | attacker cost / node cost | n* at 1% | n* at 10% | events the reserve survives (1%) | allowance refill wait for a confirm, A97/d (s) at 1% | T10 shipped policy: confirm late by (s, median t_E) | T10 reserved: flash tries |")
    L.append("|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|")
    for sf in (7, 8, 9):
        L.append(f"| {sf} | {f(R[f'r7.a.air.sf{sf}.b14'])} | {f(R[f'r7.a.air.sf{sf}.b97'])} | {f(R[f'r7.a.sf{sf}.node_air_event_confirm_path'])} | {f(R[f'r7.a.sf{sf}.attacker_cost_ratio'], 2)} | {R[f'r7.a.H1.sf{sf}.n_star']} | {R[f'r7.a.H10.sf{sf}.n_star']} | {R[f'r7.a.H1.sf{sf}.n_h_limit']} | {f(R[f'r7.a.H1.sf{sf}.sat_delay'], 1)} | {f(R[f'r7.a.T10.sf{sf}.median.old_confirm_delay'], 2)} | {R[f'r7.a.T10.sf{sf}.median.reserved_flash_tries']} |")
    L.append("\nReading. With the shipped caps (4 + 4 tries) one fully suppressed event costs the node the airtime in column 4; to spend a trailing-hour allowance of 1% takes n* such events in one hour (one every 3600/n* s). Under a per-transmission off-time of 10% the flash retries lock the sub-band and the confirm is late at once (column 10). D_max of the reserved policy: `r7.a.H1.sf*.dmax_first` = A14 + 0.32 s (a flash that started just before the confirm was due cannot be withdrawn); under the off-time the guard makes it 0. The k-th copy is bounded by D_max + (k - 1)(A97 + W) (hourly) or D_max + (k - 1) max(A97 + W, 10 A97) (off-time); values are in `r7.a.*.dmax_kth`. n* is the V18 definition ceil(B / W_e); the old policy's allowance is already short for the next confirm one event earlier or at the same count (`r7.a.*.n_first_fail` equals n*).\n")
    L.append("## 3. Simulation of the attack (SIMULATED, H-R7-A1)\n")
    L.append("Engine `src/crashguard/r7_engine.py` (its old path equals `r3_t1.r3_event` and `r6_micro.micro_event` draw for draw, `tests/test_r7_engine.py`). 6 seed sets of 200 runs per cell; primary stress: n* earlier fully suppressed events in the hour (rows with E = 1 and F = 1 of the stored event table), target event drawn from the rows with E = 1; success = the follow-up starts within D_max of becoming pending.\n")
    L.append("| Duty model | SF | policy | n earlier events | rate | lower 95% limit | median delay (s) | share never sent | share of targets dropped (node still busy) |")
    L.append("|---|---:|---|---:|---:|---:|---:|---:|---:|")
    for c in cells:
        if not c["feasible"] or c["q"] != 1.0 or c["k"] != 4:
            continue
        from crashguard.r7_analytic import MODELS, n_star

        allow = MODELS[c["model"]][1]
        nstar = n_star(c["sf"], allow) if allow else 0
        if c["n_prior"] not in (nstar, 0):
            continue
        L.append(f"| {c['model']} | {c['sf']} | {c['policy']} | {c['n_prior']}{' (primary)' if c['n_prior'] == nstar and allow else ''} | {f(c['rate'])} | {f(c['lo95'])} | {f(c['delay_median'], 2)} | {f(c['never_sent_share'], 2)} | {f(c['target_dropped_share'], 2)} |")
    L.append("\nThe T10 rows have no earlier events (the off-time is local to the frame chain). H-R7-A1 asks for at least 0.99 in every feasible primary cell: it is **not supported**; the reserve of one event fails at 1% because the follow-ups of the earlier events spend the reserve after flash frames were admitted while it was still full.\n")
    L.append("Companions (descriptive): n earlier events in {0, ceil(n*/2), 2 n*}, q = 0.5 and k = 2 are in `results/tables/r7_attack_cells.json` and the keys `r7.a1.sim.*`. 2 n* is infeasible at 10% (the events do not fit in the hour) and the rate is 0 for both policies at 1% (the allowance cannot carry that many follow-ups, whatever the policy).\n")
    L.append("### Post-run exploration (not preregistered, outside the family): the reserve sized for n_res events\n")
    L.append("| SF | duty | n_res = 1 | 2 | 4 | 8 | 16 |")
    L.append("|---:|---|---:|---:|---:|---:|---:|")
    for sf in (7, 8, 9):
        for m in ("H1", "H10"):
            row = {c["n_res"]: c for c in post if c["sf"] == sf and c["model"] == m}
            L.append(f"| {sf} | {m} | " + " | ".join(f(row[n]["rate"], 3) for n in (1, 2, 4, 8, 16)) + " |")
    L.append("\nThe reserve for 4 events keeps the follow-up on time in every run of these cells; it costs 4 x 4 x A97 + A_M of airtime: " + ", ".join(f"{R[f'r7.a.air.sf{sf}.b97'] * 16 + R[f'r7.a.air.sf{sf}.b13']:.2f} s at SF{sf} ({100 * (R[f'r7.a.air.sf{sf}.b97'] * 16 + R[f'r7.a.air.sf{sf}.b13']) / 36:.0f}% of 1%)" for sf in (7, 8, 9)) + ".\n")
    L.append("## 4. Bounded formal check (FORMAL)\n")
    tot = {p: {k: R[f"r7.formal.total.{p}.{k}"] for k in ("runs", "inv1_violations", "inv2_violations_conditional", "inv2_violations_unconditional", "conditional_runs")} for p in ("old", "reserved")}
    L.append("Model of `src/crashguard/r7_formal.py` (independent integer re-implementation): steps as time units, flash cost 1, confirm cost 4 (k tries, k in {1, 2}), cancel 3 copies, reserve R = 4k + 1, trailing window of 30 steps (hourly model) or off-time 3 x cost (T model), B in {16, 20, 24, 28, 32, 40}, up to 2 earlier confirm events and the target (confirm or cancel), the attacker choosing every ACK outcome, gaps of 0, 2 or 5 steps. An earlier run with a window of 10 steps was replaced before reporting: an event lasts about 13 steps, so earlier events never shared a window and the unconditional form could not fail. The bounds differ from V18 (B 16 to 40; at most 2 earlier events).\n")
    L.append("| Policy | configurations | Invariant 1 violations | Invariant 2 violations, reserve intact (of conditional runs) | Invariant 2 violations, unconditional |")
    L.append("|---|---:|---:|---:|---:|")
    for p in ("reserved", "old"):
        t = tot[p]
        L.append(f"| {p} | {t['runs']} | {t['inv1_violations']} | {t['inv2_violations_conditional']} of {t['conditional_runs']} | {t['inv2_violations_unconditional']} |")
    ex = [c for c in form if c["policy"] == "reserved" and c["example"]]
    ex = sorted(ex, key=lambda c: (c["example_n"], c["B"]))[0]
    L.append(f"\nInvariant 1 (class-L frames never leave less than the reserve; the check is run on the log, not on the admission code) and Invariant 2 conditional on the reserve being intact hold in the bounds. The control, the shipped policy, violates Invariant 2. The unconditional form fails for the reserved policy only with 2 earlier events (smallest case: {ex['example_n']} earlier events, B = {ex['B']}, k = {ex['k']}, model {ex['model']}; the trace is in `results/tables/r7_formal.json`): the earlier follow-ups have spent the reserve. This is the same limit as in the simulation. FORMAL here means exhaustive over the stated bounds, not a proof for all sizes.\n")
    L.append("## 5. Benign cost on the traces (TRACE_DRIVEN, H-R7-A2, run once)\n")
    L.append("LoED half 0 (1,543 devices; groups L < 10% loss, M, H >= 40%), SF7, 300 start points per device, R3 and R6-1 (13-byte micro frame), isolated events. The old path with no duty layer reproduces the stored `r6.r1.trace.*.air_over_r3` (0.507073, 0.599965, 0.939272) to 1e-5. One-sided 95% limits, cluster bootstrap over devices.\n")
    L.append("| Group | scheme | duty | delivery, reserved minus old | lower 95% limit | median time old (s) | median time reserved (s) | ratio upper 95% limit |")
    L.append("|---|---|---|---:|---:|---:|---:|---:|")
    for k_, v in a2.items():
        g, sc, m = k_.split(".")
        L.append(f"| {g} | {sc} | {m} | {v['delivery_diff']:.4f} | {v['lo95']:.4f} | {v['med_old']:.4f} | {v['med_res']:.4f} | {v['ratio_hi95']:.3f} |")
    L.append("\nH-R7-A2a (at most 1 percentage point lower delivery in every cell): **not supported**; the limit is crossed in group H (loss at least 40%) under the off-time (the time reserve admits 3 flash tries at SF7 instead of 4, so the flash is delivered less often on a lossy link). H-R7-A2b (median time at most 10% higher): supported in every cell (ratio 1.000). Under the hourly models the fall is below 0.5 points in every group. SF8 and SF9: NOT_RUN (no loss trace at these spreading factors; the ns-3 policy files are frozen and were not edited). The operating-regime boundary: with a per-transmission off-time and a link that loses 40% of frames or more, the reserve costs about 2.4 points of delivery.\n")
    L.append("## 6. Gating rule with the reserve (descriptive, H-R7-A3)\n")
    L.append("| SF | load gate (stored) | lockout gate, 10% off-time (shipped) | same with the reserve | flash tries under the off-time (shipped / reserved) | reserve at n_res = 1 as share of the 1% allowance |")
    L.append("|---|---|---|---|---|---:|")
    for sf in (7, 8, 9, 10, 11, 12):
        lg = R[f"r7.a.a3.T10.sf{sf}.load_gate"]
        L.append(f"| {sf} | {lg} | {R[f'r7.a.a3.T10.sf{sf}.lockout_gate_old']} | {R[f'r7.a.a3.T10.sf{sf}.lockout_gate_reserved']} | {R[f'r7.a.a3.T10.sf{sf}.flash_tries_old']} / {R[f'r7.a.a3.T10.sf{sf}.flash_tries_reserved']} | {R[f'r7.a.a3.H1.sf{sf}.reserve_share_of_allowance']:.3f} |")
    L.append("\nThe spreading factor at which the two-stage alert is enabled does not move: 0 steps under H1, H10 and T10 (SF7). The load gate does not depend on the reserve; the lockout gate is the same inequality (the node admits the flash when s_f + A_f / d <= T_F, and not otherwise), now enforced by the node per event, and the reserve limits the number of flash tries (3, 2, 1, 0 at SF7 to SF10 under the off-time). At SF11 and SF12 the reserve for one event takes 25% and 47% of a 1% allowance, a cost the old policy does not have.\n")
    L.append("## 7. Limits\n")
    L.append("- No result here is measured on hardware or on a commercial gateway. The attack is a model of ACK suppression with a stated attacker; selective jamming of gateways is shown to be feasible in the literature (BlindSpot), not here.\n- Exhausting the allowance needs sustained triggers (one every about 85 s at SF7 and 1%); the rate at which a detector produces such triggers was not measured.\n- n* counts the shipped caps; a node with a different cap changes it.\n- The preregistered reserve (one event) protects the next follow-up only while the reserve is intact; the sized reserve costs airtime.\n- Benign cost: SF7 only.\n")
    return "\n".join(L) + "\n"


def doc_b(R: dict) -> str:
    L = [HEAD.format(title="Round 7 B: unlinkable pseudonymous vehicle ids", scope="The design, the frame fields before and after, the formal results (unlinkability, the C4 lemmas with pseudonyms, controls), the resolution cost (H-R7-B1), the collision probability (H-R7-B2), sizes, airtime and footprint.", labels="FORMAL, MEASURED_SOFTWARE, ANALYTICAL")]
    L.append("Generated by `python -m crashguard.r7_docs` from `results/results.json` (keys `r7.b.*`, `r7.formal.b.*`). Verdicts are in `ROUND7_RESULTS.md`.\n")
    L.append("## 1. Fields that identify the vehicle or carry position (read from `FRAME_LAYOUT.md`)\n")
    L.append("| Frame | In clear today, identifies the vehicle | In clear today, links frames of one vehicle | Position | After the pseudonym design |")
    L.append("|---|---|---|---|---|")
    L.append("| Alert (97 bytes) | node id (4 bytes) | freshness field, alert counter, boot counter, event id | latitude and longitude (4 + 4 bytes), in clear | pseudonym p (4 bytes) replaces the node id; boot, counter and event id leave the clear (the base recovers them from the window entry); position and payload encrypted; tag covers boot and counter as unsent associated data |")
    L.append("| ACK (26 bytes) | node id | acked freshness field, base counter | none | the ACK names p, not the vehicle |")
    L.append("| Flash (14 or 15 bytes) | short id (2 bytes) | freshness low 16 bits, boot byte | none | p (2 bytes) replaces the short id; the freed bytes carry encrypted flags and a 2-byte coarse cell; the boot byte is dropped (15 -> 14 bytes) |")
    L.append("| Cancel (14 or 15 bytes) | short id | freshness low 16 bits, boot byte | none | as the flash |")
    L.append("| Micro-confirm (8 bytes) | none (pending index) | the index (random, per event) | 1-byte offset | unchanged; the index is chosen by the base per flash |")
    L.append("\n## 2. Design\n")
    L.append("Pseudonym p = the leading L bytes of HMAC-SHA256(k_v, \"P\" || boot (u32) || ctr (u32)); L = 2 where the frame has the 16-bit short id, L = 4 where it has the 32-bit node id. The base keeps for each vehicle the pseudonyms of the next m = 16 counters of its boot and a hash index from pseudonym to the entries; a frame whose pseudonym matches is verified with the tag under each candidate entry (the tag decides); the window moves to the matched counter. **The tag covers the frame bytes and, as associated data that is not sent, boot and counter of the entry.** Without that, two entries of one vehicle with equal pseudonyms are ambiguous: the C benchmark at L = 2 resolved 199,911 of 200,000 frames until the tag covered the counter (fixed; Python and C now resolve all). Desynchronisation: a lost run of more than m frames, or a reboot (the boot counter rises), leaves the frame unresolved; the base then tests the next three boot values for every vehicle (a linear scan, measured below) and a resolved full alert resynchronises the vehicle. Frames that do not resolve or fail the tag trigger only cell-level rate limiting. The boot-counter rule, the seen-set and the per-vehicle quarantine act on the resolved real id, so linkability exists for the base only.\n")
    L.append("Position: unlinkable ids do not hide position. The position fields of the alert are encrypted (stream cipher keyed from k_v with the nonce boot and counter, authenticated by the existing 8-byte tag: no byte is added). The flash carries at most a 2-byte coarse cell. Responders get the position from the base, not from the air. A 16-byte AEAD tag instead of the 8-byte tag would add 8 bytes: " + ", ".join(f"{1000 * R[f'r7.b.desc.air.sf{sf}.aead16_extra']:.1f} ms at SF{sf}" for sf in (7, 8, 9)) + " (ANALYTICAL). Out of scope: radio fingerprinting, timing correlation, an attacker that holds a vehicle key.\n")
    L.append("## 3. Formal results (FORMAL)\n")
    L.append("Symbolic models; the pseudonym is a pseudorandom function symbol, the window is a table entry for every alert a vehicle sends (resynchronisation succeeds), the attacker controls the channel and holds no vehicle key (Revealed keys are excluded in the lemmas). ProVerif 2.05 and Tamarin 1.12.0 in WSL, outputs in `formal/out/r7/`.\n")
    L.append("| Model or lemma | Property | Outcome | Wall time (s) |")
    L.append("|---|---|---|---:|")
    rows = [("r7_unlink.pv", "diff-equivalence: two alerts of one vehicle against two vehicles", "r7_unlink"), ("r7_unlink_many.pv", "diff-equivalence: unboundedly many alerts, one vehicle against a fresh vehicle each", "r7_unlink_many"),
            ("r7_unlink_control.pv", "control: fixed id in clear (the current design)", "r7_unlink_control"), ("r7_unlink_bootclear.pv", "control: pseudonym design with the boot counter in clear", "r7_unlink_bootclear"),
            ("r7_lemmas_alert.pv", "unique ids with the boot counter; authenticity; injective form", "r7_lemmas_alert"), ("r7_lemmas_alert_nowrite.pv", "control: boot counter not written (uniqueness must fail)", "r7_lemmas_alert_nowrite"),
            ("r7_lemmas_micro.pv", "micro-confirm authenticity, binding to the flash, micro-cancel", "r7_lemmas_micro"), ("r7_lemmas_micro_control.pv", "control: T1 not in the micro tag", "r7_lemmas_micro_control"),
            ("r7_lemmas_quarantine.pv", "no framing by the quarantine counter (strike only after resolution, tag and seen-set)", "r7_lemmas_quarantine"), ("r7_lemmas_quarantine_control.pv", "control: strike counted before the tag", "r7_lemmas_quarantine_control")]
    words = {"true": "holds", "false": "does not hold"}
    for fn, prop, k_ in rows:
        out = R[f"r7.formal.b.pv.{k_}.outcomes"].split(";")
        L.append(f"| {fn} | {prop} | {' ; '.join(words[o] if o in words else o for o in out)} | {R[f'r7.formal.b.pv.{k_}.wall_time_s']} |")
    for lem in ("executable_ts", "executable_after_car_reboot", "L4_replay_outside_window", "L4b_at_most_once", "L5_no_double_accept_with_car_reboot", "L6_base_reboot_replay", "L7_no_time_alert_can_be_stale"):
        L.append(f"| r7_alert_pseudo_fresh_bootctr.spthy: {lem} | Tamarin lemma of the round-3 model, with pseudonyms | {R[f'r7.formal.b.tam.{lem}.outcome']} | {R[f'r7.formal.b.tam.{lem}.wall_time_s']} |")
    L.append("\nReading. The pseudonym design satisfies the equivalence for two alerts and for unboundedly many; both controls fail with a trace, so the result is sensitive to what is in clear. ProVerif's output lists a termination warning; the result lines are proofs. The injective (anti-replay) forms are not provable in ProVerif because of its table semantics (the same limit as in the earlier models); they are covered by the Tamarin lemmas L4, L4b and L5, with L6 refuted as in C4 (a base reboot clears the seen-set). The lemma table of the injective no-framing form for the quarantine is not proved, only the non-injective form. The ProVerif model of the unlinkability test does not cover the micro-confirm's index and the cancel frame; those are in the lemma model. Quarantine here is the symbolic counter rule; the Python enumeration of round 6 is unchanged.\n")
    L.append("## 4. Resolution cost (MEASURED_SOFTWARE, H-R7-B1) and collisions (ANALYTICAL, H-R7-B2)\n")
    L.append(f"Machine: {R['r7.b.bench.cpu']} (Python 3.12 `hmac`; gcc -O2 in WSL, `firmware_r7/cg_r7_bench.c` with `cg_hmac_sha256` of `firmware_rd`). 1,000 vehicles, m = 16, 200,000 frames, 5 repetitions, 10% of frames after a loss of up to m - 1 frames.\n")
    L.append("| L (bytes) | Python mean (microseconds) | Python worst repetition | C mean | C worst repetition |")
    L.append("|---:|---:|---:|---:|---:|")
    for Lb in (2, 4):
        L.append(f"| {Lb} | {1e6 * R[f'r7.b.bench.python.L{Lb}.mean_per_frame']:.1f} | {1e6 * R[f'r7.b.bench.python.L{Lb}.worst_rep']:.1f} | {1e6 * R[f'r7.b.bench.c.L{Lb}.mean_per_frame']:.2f} | {1e6 * R[f'r7.b.bench.c.L{Lb}.worst_rep']:.2f} |")
    L.append(f"\nH-R7-B1 (at most 1 ms): supported (worst {1e6 * R['r7.b.hR7_B1.worst_mean_per_frame']:.1f} microseconds). The frame that follows a reboot costs {1000 * R['r7.b.resync.python.one_frame_s']:.0f} ms in Python (descriptive: a linear scan over vehicles and three boot values).\n")
    L.append("| L (bytes) | P(collision per frame), formula | expected extra candidates per frame |")
    L.append("|---:|---:|---:|")
    for Lb in range(1, 7):
        L.append(f"| {Lb} | {R[f'r7.b.hR7_B2.L{Lb}.p_collision_formula']:.3g} | {R[f'r7.b.hR7_B2.L{Lb}.extra_candidates_per_frame']:.3g} |")
    L.append(f"\nP = 1 - (1 - 2^-8L)^((n - 1) m) with n = 1,000, m = 16. Enumeration with real HMAC pseudonyms (200,000 frames, seed 42): {R['r7.b.hR7_B2.L2.p_collision_enumerated']:.4f} at L = 2 and {R['r7.b.hR7_B2.L4.p_collision_enumerated']:.4f} at L = 4 (no collision in the sample; the expected count is 0.74). H-R7-B2 (P at most 1e-6 at the frame with the smallest L, L = 2): **not supported**, and not supported at the alert's L = 4 either; the bound is met from L = 5. A collision is resolved by the tag (one more tag check per candidate; wrong attribution needs a tag collision, 2^-64 per candidate for the 8-byte tag).\n")
    L.append("## 5. Sizes, airtime and footprint (descriptive)\n")
    L.append("Frame sizes are unchanged (97, 26, 14 and 8 bytes; the 15-byte flash with the boot byte becomes 14 bytes). Footprint of the node routine `cg_r7_pseudonym` for the ESP32 (Espressif GCC 12.2.0, -Os, compile only; `scripts/r7_footprint.sh`): " + f"{R['r7.b.desc.fp.text_bytes']} bytes of code and {R['r7.b.desc.fp.literal_bytes']} bytes of literals, no static data; stack {R['r7.b.desc.fp.stack_pseudonym']} bytes for the routine, plus {R['r7.b.desc.fp.stack_hmac']} for `cg_hmac_sha256` and {R['r7.b.desc.fp.stack_sha256']} for `cg_sha256` that it calls (deepest path {R['r7.b.desc.fp.stack_pseudonym'] + R['r7.b.desc.fp.stack_hmac'] + R['r7.b.desc.fp.stack_sha256']} bytes); the HMAC and SHA-256 code ({R['r7.b.desc.fp.hmac_text']} and {R['r7.b.desc.fp.sha256_text']} bytes) is already in the node for the tag. Instruction counts and energy: NOT_RUN (no emulator, no hardware).\n")
    L.append("## 6. Limits\n")
    L.append("- The proofs are symbolic and need perfect cryptography; they say nothing about timing correlation, radio fingerprints, packet lengths or an attacker with a vehicle key.\n- The window is abstracted as an entry for every alert the vehicle sends: a vehicle that falls out of the window (more than m lost frames) or reboots is outside the proofs (the scan above handles it in the implementation).\n- The collision bound fails at the frame sizes of the layout; keeping the sizes means a tag check per collision candidate.\n- The injective form of the no-framing lemma is not proved.\n")
    return "\n".join(L) + "\n"


